InputEngineManagerAsyncWaiter::InputEngineManagerAsyncWaiter(
    InputEngineManager* proxy) : proxy_(proxy) {}

InputEngineManagerAsyncWaiter::~InputEngineManagerAsyncWaiter() = default;

void InputEngineManagerAsyncWaiter::ConnectToImeEngine(
    const std::string& ime_spec, ::mojo::PendingReceiver<::ash::ime::mojom::InputChannel> to_engine_request, ::mojo::PendingRemote<::ash::ime::mojom::InputChannel> from_engine, const std::vector<uint8_t>& extra, bool* out_success) {
  base::RunLoop loop;
  proxy_->ConnectToImeEngine(std::move(ime_spec),std::move(to_engine_request),std::move(from_engine),std::move(extra),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool InputEngineManagerAsyncWaiter::ConnectToImeEngine(
    const std::string& ime_spec, ::mojo::PendingReceiver<::ash::ime::mojom::InputChannel> to_engine_request, ::mojo::PendingRemote<::ash::ime::mojom::InputChannel> from_engine, const std::vector<uint8_t>& extra) {
  bool async_wait_result;
  ConnectToImeEngine(std::move(ime_spec),std::move(to_engine_request),std::move(from_engine),std::move(extra),&async_wait_result);
  return async_wait_result;
}

void InputEngineManagerAsyncWaiter::InitializeConnectionFactory(
    ::mojo::PendingReceiver<::ash::ime::mojom::ConnectionFactory> connection_factory, bool* out_success) {
  base::RunLoop loop;
  proxy_->InitializeConnectionFactory(std::move(connection_factory),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool InputEngineManagerAsyncWaiter::InitializeConnectionFactory(
    ::mojo::PendingReceiver<::ash::ime::mojom::ConnectionFactory> connection_factory) {
  bool async_wait_result;
  InitializeConnectionFactory(std::move(connection_factory),&async_wait_result);
  return async_wait_result;
}




