PlatformAccessProviderAsyncWaiter::PlatformAccessProviderAsyncWaiter(
    PlatformAccessProvider* proxy) : proxy_(proxy) {}

PlatformAccessProviderAsyncWaiter::~PlatformAccessProviderAsyncWaiter() = default;

void PlatformAccessProviderAsyncWaiter::DownloadImeFileTo(
    const ::GURL& url, const ::base::FilePath& file_path, ::base::FilePath* out_file_path) {
  base::RunLoop loop;
  proxy_->DownloadImeFileTo(std::move(url),std::move(file_path),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::base::FilePath* out_file_path
,
             const ::base::FilePath& file_path) {*out_file_path = std::move(file_path);
            loop->Quit();
          },
          &loop,
          out_file_path));
  loop.Run();
}

::base::FilePath PlatformAccessProviderAsyncWaiter::DownloadImeFileTo(
    const ::GURL& url, const ::base::FilePath& file_path) {
  ::base::FilePath async_wait_result;
  DownloadImeFileTo(std::move(url),std::move(file_path),&async_wait_result);
  return async_wait_result;
}




